    "Automate EC2 AMI provisioning for Kafka performance testing using Packer scripts with pre-installed Java 17+, Apache Kafka, and Spring XD binaries.",
    "Implement load generator source and load receiving sink modules as native Spring XD / Spring Integration components with configurable throughput and payload parameters.",
    "Fix Kafka source offset management by refactoring offset commit and fetch logic using modern Spring for Apache Kafka client APIs.",
    "Configure Windows CI build pipelines using dedicated Windows runner nodes to isolate and triage OS-specific test failures.",
    "Build the static GitHub Pages site using standard HTML/CSS templates or Jekyll to organize Spring XD samples, tutorials, and benchmark results.",
    "Conduct Lattice/Diego POC exploration focused on defining a pluggable Container Launcher SPI for the Spring XD runtime."
  ],
  "assumptions": [
    "AWS account access and sufficient permissions are provided to build and bake EC2 AMIs.",
    "CI server infrastructure (e.g., Jenkins/Bamboo) with Windows node access is available for build pipeline setup.",
    "Content for tutorials, architecture diagrams, and baseline samples is available for curation on the gh-pages site.",
    "All work is carried out by a single full-time software developer."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "EC2 AMI Creation for Kafka Perf Testing (U1)",
      "activity_description": "Create automated build scripts to provision an EC2 AMI loaded with required packages, JDK, Apache Kafka, and testing tools for performance runs.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Load Generator Source Module Development (U2)",
      "activity_description": "Develop and unit test a configurable load generator source module to produce synthetic data loads for perf test scenarios.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Load Receiving Sink Module Development (U3)",
      "activity_description": "Develop and unit test a load receiving sink module capable of capturing metrics and measuring incoming message throughput.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Windows CI Build Pipeline & Failure Isolation (U4)",
      "activity_description": "Configure Windows CI build jobs, run test suites, isolate failing test cases, and evaluate AMI image stability on Windows runners.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Kafka Source Offset Management Fix (U5)",
      "activity_description": "Refactor offset tracking and fetching logic in the Kafka source module to ensure accurate and efficient offset-based consumption.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Stream Performance Benchmarking (U6)",
      "activity_description": "Deploy simple streams across source, broker, and sink modules in the perf environment to execute benchmarks and log baseline throughput metrics.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Static GitHub Pages Collateral Site Setup (U7)",
      "activity_description": "Design, structure, and publish a static gh-pages site containing collateral, tutorials, benchmarks, and reference architectures for Spring XD.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Lattice/Diego POC & Pluggable SPI Design (U8)",
      "activity_description": "Continue prototyping Lattice/Diego integration, evaluate deployment risks, and draft an SPI design for pluggable runtime orchestration.",
      "most_likely_effort": 5.0
    }
  ],
  "reported_total": {
    "most_likely_effort": 25.0
  }
}
